import React from 'react';
import {
    Card,
    CardContent,
    Typography,
    Box,
    ToggleButtonGroup,
    ToggleButton,
    Skeleton,
} from '@mui/material';
import {
    Line,
    XAxis,
    YAxis,
    CartesianGrid,
    Tooltip,
    Legend,
    ResponsiveContainer,
    Area,
    ComposedChart,
} from 'recharts';
import { ChartDataPoint } from '../../types';
import { formatNumber } from '../../utils/formatters';

interface ForecastChartProps {
    data: ChartDataPoint[];
    loading?: boolean;
    title?: string;
    showConfidenceInterval?: boolean;
}

const ForecastChart: React.FC<ForecastChartProps> = ({
    data,
    loading = false,
    title = 'Stockpile Forecast',
    showConfidenceInterval = true,
}) => {
    const [timeRange, setTimeRange] = React.useState<'7d' | '30d' | '90d'>('30d');

    const handleTimeRangeChange = (
        event: React.MouseEvent<HTMLElement>,
        newRange: '7d' | '30d' | '90d' | null,
    ) => {
        if (newRange !== null) {
            setTimeRange(newRange);
        }
    };

    const filterDataByRange = (range: '7d' | '30d' | '90d') => {
        const days = range === '7d' ? 7 : range === '30d' ? 30 : 90;
        return data.slice(-days);
    };

    const filteredData = filterDataByRange(timeRange);

    const CustomTooltip = ({ active, payload, label }: any) => {
        if (active && payload && payload.length) {
            return (
                <Box
                    sx={{
                        backgroundColor: 'white',
                        p: 2,
                        border: '1px solid #E5E7EB',
                        borderRadius: 2,
                        boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
                    }}
                >
                    <Typography variant="body2" fontWeight={600} gutterBottom>
                        {label}
                    </Typography>
                    {payload.map((entry: any, index: number) => (
                        <Box key={index} display="flex" alignItems="center" gap={1} mt={0.5}>
                            <Box
                                sx={{
                                    width: 12,
                                    height: 12,
                                    borderRadius: '50%',
                                    backgroundColor: entry.color,
                                }}
                            />
                            <Typography variant="body2" color="text.secondary">
                                {entry.name}:
                            </Typography>
                            <Typography variant="body2" fontWeight={600}>
                                {formatNumber(entry.value)} Kt
                            </Typography>
                        </Box>
                    ))}
                </Box>
            );
        }
        return null;
    };

    if (loading) {
        return (
            <Card>
                <CardContent>
                    <Skeleton variant="text" width="40%" height={32} />
                    <Skeleton variant="rectangular" width="100%" height={400} sx={{ mt: 2, borderRadius: 2 }} />
                </CardContent>
            </Card>
        );
    }

    return (
        <Card>
            <CardContent sx={{ p: 3 }}>
                <Box display="flex" justifyContent="space-between" alignItems="center" mb={3}>
                    <Typography variant="h5" fontWeight={700}>
                        {title}
                    </Typography>
                    <ToggleButtonGroup
                        value={timeRange}
                        exclusive
                        onChange={handleTimeRangeChange}
                        size="small"
                        sx={{
                            '& .MuiToggleButton-root': {
                                px: 2,
                                py: 0.5,
                                borderRadius: 2,
                                fontWeight: 600,
                                fontSize: '0.875rem',
                            },
                        }}
                    >
                        <ToggleButton value="7d">7 Days</ToggleButton>
                        <ToggleButton value="30d">30 Days</ToggleButton>
                        <ToggleButton value="90d">90 Days</ToggleButton>
                    </ToggleButtonGroup>
                </Box>

                <ResponsiveContainer width="100%" height={400}>
                    <ComposedChart
                        data={filteredData}
                        margin={{ top: 10, right: 30, left: 0, bottom: 0 }}
                    >
                        <defs>
                            <linearGradient id="colorPredicted" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#0D63F4" stopOpacity={0.3} />
                                <stop offset="95%" stopColor="#0D63F4" stopOpacity={0} />
                            </linearGradient>
                            <linearGradient id="colorActual" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#16A34A" stopOpacity={0.3} />
                                <stop offset="95%" stopColor="#16A34A" stopOpacity={0} />
                            </linearGradient>
                        </defs>
                        <CartesianGrid strokeDasharray="3 3" stroke="#E5E7EB" />
                        <XAxis
                            dataKey="date"
                            stroke="#6B7280"
                            style={{ fontSize: '0.75rem', fontWeight: 600 }}
                            tickFormatter={(value) => {
                                const date = new Date(value);
                                return `${date.getMonth() + 1}/${date.getDate()}`;
                            }}
                        />
                        <YAxis
                            stroke="#6B7280"
                            style={{ fontSize: '0.75rem', fontWeight: 600 }}
                            tickFormatter={(value) => `${formatNumber(value, 0)}`}
                            label={{
                                value: 'Stockpile (Kt)',
                                angle: -90,
                                position: 'insideLeft',
                                style: { fontSize: '0.875rem', fontWeight: 600, fill: '#374151' },
                            }}
                        />
                        <Tooltip content={<CustomTooltip />} />
                        <Legend
                            wrapperStyle={{ fontSize: '0.875rem', fontWeight: 600 }}
                            iconType="line"
                        />

                        {showConfidenceInterval && filteredData[0]?.lower && (
                            <Area
                                type="monotone"
                                dataKey="lower"
                                stroke="none"
                                fill="#0D63F4"
                                fillOpacity={0.1}
                                name="Confidence Lower"
                                legendType="none"
                            />
                        )}
                        {showConfidenceInterval && filteredData[0]?.upper && (
                            <Area
                                type="monotone"
                                dataKey="upper"
                                stroke="none"
                                fill="#0D63F4"
                                fillOpacity={0.1}
                                name="Confidence Upper"
                                legendType="none"
                            />
                        )}

                        <Line
                            type="monotone"
                            dataKey="predicted"
                            stroke="#0D63F4"
                            strokeWidth={3}
                            dot={{ fill: '#0D63F4', r: 4 }}
                            activeDot={{ r: 6 }}
                            name="Predicted"
                        />
                        <Line
                            type="monotone"
                            dataKey="actual"
                            stroke="#16A34A"
                            strokeWidth={3}
                            dot={{ fill: '#16A34A', r: 4 }}
                            activeDot={{ r: 6 }}
                            name="Actual"
                            strokeDasharray="5 5"
                        />
                    </ComposedChart>
                </ResponsiveContainer>
            </CardContent>
        </Card>
    );
};

export default ForecastChart;
